import { PlaneGeometry, MeshBasicNodeMaterial, Mesh } from 'three/webgpu';
import { texture } from 'three/tsl';

export default function createNode(config, ctx) {
  // Atlas region aspect ratio: 512/320 ≈ 1.6
  const aspectRatio = 512 / 320;

  // Default card dimensions
  const cardHeight = config.cardHeight ?? 1.2;
  const cardWidth = cardHeight * aspectRatio;

  // Create plane geometry
  const geometry = new PlaneGeometry(cardWidth, cardHeight);

  // Load texture
  const imageUrl = config.imageUrl ?? '/prism-assets/chrome/ceramic-grain.map.png';
  const textureMap = ctx.textureLoader.load(imageUrl);

  // Create material with TSL texture node
  const colorNode = texture(textureMap);
  const material = new MeshBasicNodeMaterial({
    colorNode: colorNode,
  });

  // Create mesh at scene position
  const mesh = new Mesh(geometry, material);
  mesh.position.set(0, -0.3, 0);

  // Setup resource cleanup
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (textureMap) textureMap.dispose();
  };

  mesh.userData.handlers = {};

  return mesh;
}
